GUIDES = {
 "cold_flu":{"title":"Cold & flu season","points":["Wash hands regularly and avoid touching your face with unwashed hands.","Improve indoor ventilation and consider a well-fitting mask in crowded indoor spaces.","Stay home when unwell where possible and follow local public-health guidance.","Ask a qualified clinician about vaccination eligibility and timing."],"seek":"Seek medical advice for worsening symptoms, persistent fever, or concerns; urgent symptoms need urgent care."},
 "cold_safety":{"title":"Cold-weather safety","points":["Dress in dry layers and cover exposed skin in cold or windy conditions.","Keep indoor spaces safely warm; never use outdoor cooking devices indoors.","Check on older adults, infants and people with chronic conditions during cold spells.","Watch for unusual drowsiness, confusion, slurred speech or loss of coordination."],"seek":"Suspected hypothermia is an emergency. Move to a warm place and seek urgent medical help."},
 "hydration_nutrition":{"title":"Hydration & nutrition","points":["Drink fluids regularly; needs vary with activity, health and climate.","Choose balanced meals with vegetables, fruit, protein and whole grains.","Use safe food storage and clean drinking water at public gatherings.","Avoid using supplements or medicines as a substitute for professional advice."],"seek":"Seek medical advice for inability to keep fluids down, fainting or signs of significant dehydration."},
 "festival_crowd":{"title":"Festival crowd health","points":["Identify first-aid points, accessible exits and emergency vehicle access before the event.","Provide clean drinking water, handwashing and hygienic food handling.","Plan shaded/warm rest areas and clear signage for vulnerable attendees.","Use trained staff and a documented escalation and communication plan."],"seek":"For a serious incident, activate the event emergency plan and contact local emergency services."}
}
def get_guide(category):
    return GUIDES.get(category, GUIDES["cold_flu"])
